    @Override protected void onResume(){super.onResume();reload();}
    private void reload(){worker.execute(()->{try{Ledger.Data latest=store.read();runOnUiThread(()->{if(isDestroyed())return;data=latest;if(!billCategory.isEmpty()){try{data.category(billCategory);}catch(IllegalArgumentException e){billCategory="";}}loaded=true;render();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;body.removeAllViews();body.addView(Ui.text(this,"账本读取失败，请保留数据后重试。\n"+e.getMessage(),14,Ui.DANGER));body.addView(Ui.action(this,"重新读取",false,this::reload));});}});}
    private void perform(Work task,String message,Runnable success){if(busy){toast("正在保存，请稍候");return;}busy=true;worker.execute(()->{try{task.run();Ledger.Data latest=store.read();runOnUiThread(()->{if(isDestroyed())return;data=latest;busy=false;if(success!=null)success.run();render();if(message!=null)toast(message);});}catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;busy=false;toast("操作未完成："+e.getMessage());});}});}
    private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
    private String money(long value){return data.hide?"••••":Ledger.money(value);}
