    private TextView monthAction(){return Ui.smallAction(this,Ledger.monthLabel(month)+"  ⌄",()->pickMonth(month,false,m->{month=m;dayFilter=null;statsAnchor=m.isAfter(YearMonth.from(Ledger.today()))?Ledger.today():m.equals(YearMonth.from(Ledger.today()))?Ledger.today():m.atDay(1);selectedBucket=-1;shown=80;render();}));}
