    private void renderHome(){monthSelector();List<Ledger.Entry> rows=monthRows();long income=Ledger.total(rows,"income"),expense=Ledger.total(rows,"expense");LinearLayout balance=Ui.card(this,Ui.GREEN);balance.addView(Ui.text(this,"本月结余  / CNY",12,0xFFD1E0D5));Ui.space(balance,12);balance.addView(Ui.bold(this,"¥ "+money(income-expense),37,Ui.WHITE));Ui.space(balance,23);LinearLayout totals=Ui.row(this);Ui.weight(totals,metric("↙ 本月收入",income,Ui.WHITE));Ui.weight(totals,metric("↗ 本月支出",expense,Ui.WHITE));balance.addView(totals);body.addView(balance);
        section("预算，心中有数","管理预算  ›",()->navigate("budget"));Ledger.Budget budget=data.budget(month);LinearLayout preview=Ui.card(this,0xFFEAF0E3);if(budget.total==null){preview.addView(Ui.bold(this,"给这个月定个小目标  ＋",17,Ui.GREEN));Ui.space(preview,8);preview.addView(Ui.text(this,"设置预算，让每一笔花销更从容。",12,Ui.MUTED));}else{long remaining=budget.total-expense;preview.addView(Ui.bold(this,(remaining<0?"已超支":"本月还可用")+"  ¥"+money(Math.abs(remaining)),19,remaining<0?Ui.DANGER:Ui.GREEN));Ui.space(preview,15);preview.addView(progress(expense,budget.total));Ui.space(preview,9);preview.addView(between("已用 "+(data.hide?"••":String.format(Locale.US,"%.1f",expense*100d/budget.total))+"%","总预算 ¥"+money(budget.total),10));}preview.setOnClickListener(v->navigate("budget"));preview.setFocusable(true);body.addView(preview);Ui.space(body,11);body.addView(Ui.text(this,"慢慢记录，让每一笔花销都有着落。",11,Ui.MUTED));
        section("最近账目","查看全部  ›",()->{billType="all";billCategory="";keyword="";dayFilter=null;navigate("bills");});if(rows.isEmpty())empty(body,"这个月还没有账目","从一笔小小的记录开始。",true);else for(int i=0;i<Math.min(rows.size(),6);i++)body.addView(entryRow(rows.get(i)));
    }
    private LinearLayout metric(String label,long amount,int color){LinearLayout block=Ui.column(this);block.addView(Ui.text(this,label,11,color==Ui.WHITE?0xFFD1E0D5:Ui.MUTED));Ui.space(block,7);TextView value=Ui.bold(this,"¥ "+money(amount),18,color);value.setAutoSizeTextTypeUniformWithConfiguration(11,18,1,android.util.TypedValue.COMPLEX_UNIT_SP);value.setSingleLine(true);block.addView(value);return block;}
